[{"order":1,"type":"heading","text":"Streaming, Suspense, and Progressive Rendering in Next.js"},{"order":2,"type":"paragraph","text":"Modern web applications strive to deliver content as fast as possible. In Next.js, streaming and React Suspense allow you to break down your page HTML into smaller chunks and progressively stream those chunks from the server to the client."},{"order":3,"type":"subheading","text":"Understanding Progressive Rendering"},{"order":4,"type":"paragraph","text":"Traditional Server-Side Rendering (SSR) requires the server to fetch all data for a page before sending any HTML to the browser. If one data request is slow, the entire page render is blocked. Progressive rendering with streaming changes this by allowing the server to send the immediate shell of the page first, followed by dynamic content as it becomes ready."},{"order":5,"type":"subheading","text":"Using React Suspense for Streaming"},{"order":6,"type":"paragraph","text":"React Suspense lets you wrap a component that relies on asynchronous data fetching. While the data is loading, Suspense immediately falls back to rendering a loading state, such as a skeleton or spinner."},{"order":7,"type":"code","text":"import { Suspense } from 'react';
import { ProductDetails, ProductSkeleton } from '@/components/product';
import { Reviews, ReviewsSkeleton } from '@/components/reviews';

export default async function ProductPage({ params }) {
  const { id } = params;

  return (
    <main className="container">
      <h1>Product Dashboard</h1>

      <Suspense fallback={<ProductSkeleton />}>
        <ProductDetails id={id} />
      </Suspense>

      <Suspense fallback={<ReviewsSkeleton />}>
        <Reviews id={id} />
      </Suspense>
    </main>
  );
}"},{"order":8,"type":"subheading","text":"File-based Streaming with loading.js"},{"order":9,"type":"paragraph","text":"Next.js provides a built-in convention for streaming using loading.js files. When you place a loading.js file inside a route directory, Next.js automatically wraps your page component inside a React Suspense boundary."},{"order":10,"type":"code","text":"// app/dashboard/loading.js
export default function DashboardLoading() {
  return (
    <div className="flex items-center justify-center min-h-screen">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900"></div>
    </div>
  );
}"},{"order":11,"type":"subheading","text":"Benefits of Streaming and Suspense"},{"order":12,"type":"bullet_point","text":"Improved Time to First Byte (TTFB): Users receive the initial HTML shell instantly."},{"order":13,"type":"bullet_point","text":"Better Cumulative Layout Shift (CLS): Fallbacks prevent layout jumps by reserving space for incoming content."},{"order":14,"type":"bullet_point","text":"Prioritized Loading: Critical above-the-fold content loads before lower-priority components."}]
